#include "bits/stdc++.h"

using namespace std;

using ll = long long;

pair<int, int> merge(pair<int, int> a, pair<int, int> b) {
    a.second += b.second;
    if (a.first && b.first) {
        a.second++;
        a.first = 0;
    } else {
        a.first |= b.first;
    }
    return a;
}

void solve () {
    int n;
    cin >> n;
    vector<vector<pair<int, int>>> g(n);
    for (int i = 0; i + 1 < n; i++) {
        int x, y;
        cin >> x >> y;
        x--, y--;
        g[x].push_back({y, 1});
        g[y].push_back({x, 0});
    }
    vector<pair<int, int>> dp(n);
    auto dfs = [&] (auto&& dfs, int v, int pr, int want) -> void {
        dp[v] = {0, 0};
        for (auto& [u, w] : g[v]) {
            if (u != pr) {
                dfs(dfs, u, v, w == 1);
                dp[v] = merge(dp[v], dp[u]);
            }
        }
        if (want && !dp[v].first) {
            dp[v].first = 1;
        }
        if (!want && dp[v].first) {
            dp[v].second++;
            dp[v].first = 0;
        }
    };
    dfs(dfs, 0, 0, 0);
    int ans = dp[0].second + dp[0].first;
    auto rec = [&] (auto&& rec, int v, int pr, pair<int, int> res) -> void {
        vector<pair<int, int>> sons;
        {
            auto nres = res;
            for (auto& [u, w] : g[v]) {
                if (u != pr) {
                    sons.push_back({u, w});
                    nres = merge(nres, dp[u]);
                }
            }
            ans = min(ans, nres.first + nres.second);
        }
        int sz = sons.size();
        vector<pair<int, int>> pref(sz + 1, {0, 0}), suf(sz + 1, {0, 0});
        pref[0] = res;
        for (int i = 0; i < sz; i++) {
            pref[i + 1] = merge(pref[i], dp[sons[i].first]);
        }
        for (int i = sz - 1; i >= 0; i--) {
            suf[i] = merge(suf[i + 1], dp[sons[i].first]);
        }
        for (int i = 0; i < sz; i++) {
            auto to = merge(pref[i], suf[i + 1]);
            auto [u, w] = sons[i];
            if (w == 0 && !to.first) {
                to.first = 1;
            }
            if (w == 1 && to.first) {
                to.second++;
                to.first = 0;
            }
            rec(rec, u, v, to);

        }
    };
    rec(rec, 0, 0, {0, 0});
    cout << ans << '\n';
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int t = 1;
    cin >> t;
    while (t--) {
        solve();
    }
}
